$purchaseSummary=qrow("SELECT COUNT(*) month_count,COALESCE(SUM(CASE WHEN status IN ('ordered','received') THEN total ELSE 0 END),0) month_total FROM purchase_orders WHERE order_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01') AND order_date<DATE_FORMAT(CURDATE()+INTERVAL 1 MONTH,'%Y-%m-01')");
$purchaseWaiting=qrow("SELECT COUNT(*) count,COALESCE(SUM(total),0) total FROM purchase_orders WHERE status='ordered'");
$recentPurchases=qall('SELECT po.po_code,po.order_date,po.total,po.status,s.name supplier FROM purchase_orders po LEFT JOIN suppliers s ON s.id=po.supplier_id ORDER BY po.id DESC LIMIT 5');
$purchaseLabels=['draft'=>'Draf','ordered'=>'Dipesan','received'=>'Diterima','cancelled'=>'Dibatalkan'];
// Order value is operational sales, not confirmed cash receipts or accounting profit.
$period = qrow("SELECT COALESCE(SUM(CASE WHEN created_at >= DATE_FORMAT(CURDATE(),'%Y-%m-01') THEN total ELSE 0 END),0) current_total, COALESCE(SUM(CASE WHEN created_at < DATE_FORMAT(CURDATE(),'%Y-%m-01') THEN total ELSE 0 END),0) previous_total, SUM(created_at >= DATE_FORMAT(CURDATE(),'%Y-%m-01')) current_orders FROM orders WHERE status <> 'Dibatalkan' AND created_at >= DATE_FORMAT(CURDATE() - INTERVAL 1 MONTH,'%Y-%m-01') AND created_at < CURDATE() + INTERVAL 1 DAY");
$attention = qrow("SELECT (SELECT COUNT(*) FROM orders WHERE status='Diproses') processing, (SELECT COUNT(*) FROM orders WHERE status='Dikemas') packing, (SELECT COUNT(*) FROM products WHERE stock<=10) low_stock, (SELECT COUNT(*) FROM products WHERE stock=0) empty_stock");
$trend = qall("SELECT DATE_FORMAT(created_at,'%Y-%m') month, SUM(total) total FROM orders WHERE status <> 'Dibatalkan' AND created_at >= DATE_FORMAT(CURDATE() - INTERVAL 5 MONTH,'%Y-%m-01') AND created_at < CURDATE() + INTERVAL 1 DAY GROUP BY DATE_FORMAT(created_at,'%Y-%m') ORDER BY month");
$trendMap=array_column($trend,'total','month'); $chart=[];
for($i=5;$i>=0;$i--){$date=strtotime(date('Y-m-01')." -$i months");$chart[]=['label'=>date('M Y',$date),'total'=>(float)($trendMap[date('Y-m',$date)]??0)];}
$peak=max(1,...array_column($chart,'total'));
$sales=(float)($period['current_total']??0);$previous=(float)($period['previous_total']??0);
$change=$previous>0?($sales-$previous)/$previous*100:null;
$statuses=qall('SELECT status,COUNT(*) count FROM orders GROUP BY status');
$statusCounts=array_column($statuses,'count','status');
$statusVisuals=['Diproses'=>['color'=>'#d5a34c','icon'=>'list','hint'=>'Periksa pesanan masuk'],'Dikemas'=>['color'=>'#8b83ba','icon'=>'box','hint'=>'Siapkan barang dan kemasan'],'Dikirim'=>['color'=>'#639bb5','icon'=>'truck','hint'=>'Pantau pengiriman'],'Selesai'=>['color'=>'#54876b','icon'=>'clipboard','hint'=>'Pesanan telah selesai'],'Dibatalkan'=>['color'=>'#c2786c','icon'=>'logout','hint'=>'Pesanan dibatalkan']];
foreach($statusCounts as $label=>$count)if(!isset($statusVisuals[$label]))$statusVisuals[$label]=['color'=>'#85918a','icon'=>'list','hint'=>'Status lainnya'];
$orderTotal=array_sum($statusCounts);$segments=[];$offset=0;
foreach($statusVisuals as $label=>$visual){$end=$offset+($orderTotal>0?(int)($statusCounts[$label]??0)/$orderTotal*100:0);if($end>$offset)$segments[]=$visual['color'].' '.round($offset,4).'% '.round($end,4).'%';$offset=$end;}
$donutBackground=$segments?'conic-gradient('.implode(',',$segments).')':'#e8ede9';
$productTotal=(int)($k['products']??0);$emptyStock=(int)($attention['empty_stock']??0);$thinStock=max(0,(int)($attention['low_stock']??0)-$emptyStock);$safeStock=max(0,$productTotal-$thinStock-$emptyStock);
$stockVisuals=[['label'=>'Stok aman','count'=>$safeStock,'color'=>'#54876b','hint'=>'Lebih dari 10 unit'],['label'=>'Stok menipis','count'=>$thinStock,'color'=>'#d5a34c','hint'=>'1–10 unit'],['label'=>'Stok habis','count'=>$emptyStock,'color'=>'#c2786c','hint'=>'0 unit']];
?>
